   554  otError Ip6::HandleOptions(Message &aMessage, Header &aHeader, bool &aForward)
   555  {
   556      otError        error = OT_ERROR_NONE;
   557      HopByHopHeader hbhHeader;
   558      OptionHeader   optionHeader;
   559      uint16_t       endOffset;
   560
   561      VerifyOrExit(aMessage.Read(aMessage.GetOffset(), sizeof(hbhHeader), &hbhHeader) == sizeof(hbhHeader),
   562                   error = OT_ERROR_PARSE);
   563      endOffset = aMessage.GetOffset() + (hbhHeader.GetLength() + 1) * 8;
   564
   565      VerifyOrExit(endOffset <= aMessage.GetLength(), error = OT_ERROR_PARSE);
   566
   567      aMessage.MoveOffset(sizeof(optionHeader));
   568
   569      while (aMessage.GetOffset() < endOffset)
   570      {
   571          VerifyOrExit(aMessage.Read(aMessage.GetOffset(), sizeof(optionHeader), &optionHeader) == sizeof(optionHeader),
   572                       error = OT_ERROR_PARSE);
   573
   574          if (optionHeader.GetType() == OptionPad1::kType)
   575          {
   576              aMessage.MoveOffset(sizeof(OptionPad1));
   577              continue;
   578          }
   579
   580          VerifyOrExit(aMessage.GetOffset() + sizeof(optionHeader) + optionHeader.GetLength() <= endOffset,
   581                       error = OT_ERROR_PARSE);
   582
   583          switch (optionHeader.GetType())
   584          {
   585          case OptionMpl::kType:
   586              SuccessOrExit(error = mMpl.ProcessOption(aMessage, aHeader.GetSource(), aForward));
   587              break;
   588
   589          default:
   590              switch (optionHeader.GetAction())
   591              {
   592              case OptionHeader::kActionSkip:
   593                  break;
   594
   595              case OptionHeader::kActionDiscard:
   596                  ExitNow(error = OT_ERROR_DROP);
   597
   598              case OptionHeader::kActionForceIcmp:
   599                  // TODO: send icmp error
   600                  ExitNow(error = OT_ERROR_DROP);
   601
   602              case OptionHeader::kActionIcmp:
   603                  // TODO: send icmp error
   604                  ExitNow(error = OT_ERROR_DROP);
   605              }
   606
   607              break;
   608          }
   609
   610          aMessage.MoveOffset(sizeof(optionHeader) + optionHeader.GetLength());
   611      }
   612
   613  exit:
   614      return error;
   615  }
