   144  otError Message::AppendUintOption(uint16_t aNumber, uint32_t aValue)
   145  {
   146      uint16_t length = sizeof(aValue);
   147      uint8_t *value;
   148
   149      aValue = Encoding::BigEndian::HostSwap32(aValue);
   150      value  = reinterpret_cast<uint8_t *>(&aValue);
   151
   152      // skip preceding zeros
   153      while (value[0] == 0 && length > 0)
   154      {
   155          value++;
   156          length--;
   157      }
   158
   159      return AppendOption(aNumber, length, value);
   160  }
